    const validateInput = this.validatorFor(tool);
    if (!validateInput(input)) {
      const issues = describeIssues(validateInput.errors ?? []);
      log.warn('tool', 'input rejected', {name, issues});
      return {result: `Invalid input for tool "${name}": ${issues.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    ... unchanged tail
