  private validatorFor(tool: StoredTool): ValidateFunction {
    const resolved = this.resolveDefinition(tool.definitionSource);
    const schema = typeof tool.definitionSource === 'function' ? resolved.inputSchema : tool.registerSchema;
    const cached = tool.validators.get(schema);
    if (cached) return cached;
    const compiled = compileSchema(resolved.name, schema);
    tool.validators.set(schema, compiled);
    return compiled;
  }
}
